$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$source=(Get-Content -Raw (Join-Path $root 'modules/audio-routing/streamerbot/audio-routing-engine.cs')).Replace('public class CPHInline {','public class AudioInline { public FakeCPH CPH=new FakeCPH(); public System.Collections.Generic.Dictionary<string,object> args=new System.Collections.Generic.Dictionary<string,object>();')
$fake=@'
using System;using System.Collections.Generic;using System.Linq;using Newtonsoft.Json.Linq;
public class FakeCPH {
 public Dictionary<string,object> Globals=new Dictionary<string,object>();public Dictionary<string,JObject> Masks=new Dictionary<string,JObject>();public List<string> Writes=new List<string>();
 public bool Connected=true,FailList,FailConfigSave,FailStateSave;public string FailWrite="",Mismatch="";public int RunningBeforeWrites;
 public FakeCPH(){foreach(string name in new[]{"Music","Mic","Game","game","Image","Browser"})Masks[name]=Mask(true,true,true,true,true,true);}
 public static JObject Mask(params bool[] flags){return new JObject(Enumerable.Range(1,6).Select(i=>new JProperty(i.ToString(),flags[i-1])));}
 public T GetGlobalVar<T>(string key,bool persisted){return Globals.ContainsKey(key)?(T)Globals[key]:default(T);}
 public void SetGlobalVar(string key,object value,bool persisted){if(FailConfigSave&&key=="portable.audioRouting.config"||FailStateSave&&key=="portable.audioRouting.state")throw new Exception("Synthetic persistence failure");Globals[key]=value;}
 public void WebsocketBroadcastJson(string json){var p=JObject.Parse(json)["payload"];if((string)p["operation"]?["status"]=="running"&&Writes.Count==0)RunningBeforeWrites++;}
 public void LogError(string message){}public bool ObsIsConnected(){return Connected;}
 public string ObsSendRaw(string type,string data,int connection){if(connection!=0)throw new Exception("Wrong OBS connection");var args=JObject.Parse(data);string name=(string)args["inputName"];
  if(type=="GetInputList"){if(FailList)return "{\"requestStatus\":{\"result\":false}}";return new JObject{["inputs"]=new JArray(Masks.Keys.Select(n=>new JObject{["inputName"]=n,["inputKind"]=n=="Image"?"image_source":n=="Browser"?"browser_source":n=="Game"?"game_capture":"wasapi_input_capture"}))}.ToString();}
  if(type=="GetInputSettings")return new JObject{["inputSettings"]=new JObject{["capture_audio"]=name=="Game",["reroute_audio"]=name=="Browser",["url"]="https://example.invalid/private?secret=fixture"}}.ToString();
  if(type=="GetInputAudioTracks")return new JObject{["inputAudioTracks"]=Masks[name]}.ToString();
  if(type=="SetInputAudioTracks"){Writes.Add(name);if(name==FailWrite)return "{\"requestStatus\":{\"result\":false}}";if(name!=Mismatch)Masks[name]=(JObject)args["inputAudioTracks"].DeepClone();return "{}";}
  throw new Exception("Unexpected fixture request");
 }
}
public static class Recorder {
 public const string Config="{\"version\":2,\"gameAudioVodSafe\":true,\"sourceRouting\":{\"Music\":\"liveOnly\",\"Mic\":\"vodSafe\",\"Game\":\"game\",\"Missing\":\"vodSafe\"}}";
 public static void Concurrent(){var shared=new FakeCPH();shared.Globals["portable.audioRouting.config"]=Config;System.Threading.Tasks.Parallel.For(0,60,index=>{var engine=new AudioInline();engine.CPH=shared;engine.args["audioRoutingMode"]=index%3==0?"toggle":index%3==1?"apply":"save";engine.args["configJson"]="{\"sourceRouting\":{\"Music\":\"liveOnly\",\"Mic\":\"vodSafe\",\"Game\":\"game\",\"Missing\":\"vodSafe\"}}";engine.args["requestId"]="parallel-"+index;engine.Execute();});var c=JObject.Parse((string)shared.Globals["portable.audioRouting.config"]);if(!(bool)c["gameAudioVodSafe"]||((JObject)c["sourceRouting"]).Count!=4||shared.Writes.Count!=120)throw new Exception("Concurrent Save/Apply/Toggle lost configuration or duplicated a mutation");}
}
'@
$refs=@((Get-ChildItem -LiteralPath (Join-Path $PSHOME 'ref') -Filter '*.dll').FullName)+(Join-Path $PSHOME 'Newtonsoft.Json.dll')
Add-Type -TypeDefinition ('namespace AudioRoutingTest{'+$fake+'}namespace AudioRoutingTest{'+$source+'}') -ReferencedAssemblies $refs -CompilerOptions '/nowarn:1701,1702'
function Assert($condition,$message){if(-not $condition){throw $message}}
function Run($engine,[hashtable]$arguments){$engine.args.Clear();foreach($v in $arguments.GetEnumerator()){$engine.args[$v.Key]=$v.Value};[void]$engine.Execute()}
function Payload($engine){return ($engine.CPH.Globals['portable.audioRouting.state']|ConvertFrom-Json).payload}
function Flag($engine,$name,$track){return [bool]::Parse($engine.CPH.Masks[$name][$track].ToString())}
$fresh=[AudioRoutingTest.AudioInline]::new();Run $fresh @{audioRoutingMode='initialize';requestId='fresh'};Assert ($fresh.CPH.Writes.Count -eq 0) 'Initialize must not change OBS';Assert (@((Payload $fresh).config.sourceRouting.PSObject.Properties).Count -eq 0) 'Fresh map must not contain private seeds'
$engine=[AudioRoutingTest.AudioInline]::new();$engine.CPH.Globals['portable.audioRouting.config']=[AudioRoutingTest.Recorder]::Config
Run $engine @{audioRoutingMode='refresh';requestId='read'};Assert ($engine.CPH.Writes.Count -eq 0) 'Refresh must be read-only';Assert (-not ((Payload $engine).sources|ConvertTo-Json -Depth 10).Contains('secret=fixture')) 'Inventory must not publish URL credentials'
Run $engine @{audioRoutingMode='save';configJson='{"gameAudioVodSafe":false}';requestId='save'};Assert ($engine.CPH.Writes.Count -eq 0) 'Save must not apply tracks';Assert (@((Payload $engine).config.sourceRouting.PSObject.Properties).Count -eq 4) 'Partial saves must preserve mappings'
Run $engine @{audioRoutingMode='apply';configJson='{}';requestId='apply'};$p=Payload $engine;Assert ($engine.CPH.Writes.Count -eq 3) 'Only available exact-name managed sources may be changed';Assert ((Flag $engine 'Music' '1') -and -not (Flag $engine 'Music' '2')) 'Live only must use track 1';Assert ((Flag $engine 'Mic' '1') -and (Flag $engine 'Mic' '2')) 'VOD safe must use tracks 1 and 2';Assert (-not (Flag $engine 'Game' '2')) 'Game VOD off must remove track 2';Assert ((Flag $engine 'game' '3')) 'Differently cased unmanaged source must remain unchanged';Assert (-not (Flag $engine 'Mic' '3') -and -not (Flag $engine 'Mic' '6')) 'Managed complete masks must disable tracks 3-6';Assert (($p.results|Where-Object name -eq 'Missing').status -eq 'skipped') 'Missing mapping must remain saved and skipped';Assert ($engine.CPH.RunningBeforeWrites -eq 1) 'Running state must persist before mutations'
Run $engine @{audioRoutingMode='apply';configJson='{}';requestId='apply'};Assert ($engine.CPH.Writes.Count -eq 3) 'Duplicate completed request must not repeat mutations'
Run $engine @{audioRoutingMode='toggle';requestId='toggle'};Assert ((Flag $engine 'Game' '2') -and (Payload $engine).config.gameAudioVodSafe) 'Toggle must flip saved preference and apply';Assert ((Payload $engine).lastRequestId -eq 'toggle') 'Terminal acknowledgement must match request'
$before=$engine.CPH.Globals['portable.audioRouting.config'];$writes=$engine.CPH.Writes.Count;Run $engine @{audioRoutingMode='save';configJson='{broken';requestId='bad'};Assert ($before -eq $engine.CPH.Globals['portable.audioRouting.config'] -and (Payload $engine).operation.status -eq 'error') 'Malformed data must not overwrite config';Run $engine @{audioRoutingMode='save';configJson='{"sourceRouting":{"Mic":"invalid"}}'};Assert ($before -eq $engine.CPH.Globals['portable.audioRouting.config']) 'Invalid classifications must be rejected'
$engine.CPH.FailWrite='Music';Run $engine @{audioRoutingMode='apply';configJson='{}';requestId='reject'};Assert ((Payload $engine).operation.status -eq 'partial' -and ((Payload $engine).results|Where-Object name -eq 'Music').status -eq 'failed') 'Rejected OBS response must never report applied';$engine.CPH.FailWrite='';$engine.CPH.Mismatch='Game';$engine.CPH.Masks['Game']=[AudioRoutingTest.FakeCPH]::Mask($false,$false,$true,$true,$true,$true);Run $engine @{audioRoutingMode='apply';configJson='{}';requestId='mismatch'};Assert (((Payload $engine).results|Where-Object name -eq 'Game').status -eq 'failed') 'Readback mismatch must be reported';$engine.CPH.Mismatch=''
$engine.CPH.FailList=$true;$writes=$engine.CPH.Writes.Count;Run $engine @{audioRoutingMode='apply';configJson='{}';requestId='bad-inventory'};Assert (-not (Payload $engine).obsAvailable -and $engine.CPH.Writes.Count -eq $writes -and (Payload $engine).operation.status -eq 'error') 'Failed inventory must not report connected/applied';$engine.CPH.FailList=$false;$engine.CPH.Connected=$false;Run $engine @{audioRoutingMode='refresh'};Assert (-not (Payload $engine).obsAvailable) 'Disconnected OBS must be unavailable';$engine.CPH.Connected=$true
$engine.CPH.FailConfigSave=$true;Run $engine @{audioRoutingMode='apply';configJson='{}';requestId='save-fail'};Assert ($engine.CPH.Writes.Count -eq $writes) 'Config save failure must prevent OBS writes';$engine.CPH.FailConfigSave=$false;$engine.CPH.FailStateSave=$true;Run $engine @{audioRoutingMode='apply';configJson='{}';requestId='state-fail'};Assert ($engine.CPH.Writes.Count -eq $writes) 'Running-state save failure must prevent mutations';$engine.CPH.FailStateSave=$false
[AudioRoutingTest.Recorder]::Concurrent()
Write-Output 'Actual Audio Routing C# passed: full six-track rules, exact-name/unmanaged/missing inputs, read-only Save/Refresh/startup, malformed/persistence failure, rejected writes, readback/partial errors, request acknowledgements and concurrent Save/Apply/Toggle. Synthetic OBS only.'
